# Stateful security group vs stateless NACL (model of the idea)
# Client 203.0.113.5 (port 50000) calls a web server on port 443.
def sg_allows_request(port):
    return port == 443            # SG: one inbound allow rule

def sg_allows_reply():
    return True                   # stateful: replies to allowed requests pass automatically

def nacl_allows(direction, port, rules):
    return (direction, port) in rules   # stateless: every packet is checked on its own

nacl_missing = {("in", 443)}
nacl_full = {("in", 443), ("out", 50000)}   # also allow the ephemeral reply port

print("request to 443 allowed by SG:", sg_allows_request(443))
print("reply allowed by SG (no rule needed):", sg_allows_reply())
for name, rules in (("NACL without return rule", nacl_missing), ("NACL with return rule", nacl_full)):
    req = nacl_allows("in", 443, rules)
    rep = nacl_allows("out", 50000, rules)
    print(name, "-> request", req, ", reply", rep, ", works:", req and rep)
